    29→async function injectOgTagsForRoute(req: any, url: string, template: string, storage: any): Promise<string> {
    30→  if (!storage) return template;
    31→  const basePath = process.env.EXPRESS_BASE_PATH || '';
    32→  const cleanPath = (basePath ? url.replace(basePath, '') : url).split('?')[0];
    33→  const baseUrl = `${req.protocol}://${req.headers.host}`;
    34→
    35→  try {
    36→    // /news/:id  (e.g. /news/abc123)
