    38→    if (newsPathMatch) {
    39→      const article = await storage.getNews(newsPathMatch[1]);
    40→      if (article) {
    41→        return injectMetaTagsIntoHtml(template, {
    42→          title: article.title,
    43→          description: article.excerpt || (article.content || '').replace(/<[^>]*>/g, '').substring(0, 160),
    44→          image: resolveImageUrl(article.image || '', baseUrl),
    45→          url: `${baseUrl}/news/${newsPathMatch[1]}`,
    46→          type: 'article',
    47→          siteName: 'Peg Slam',
    48→        });
    49→      }
    50→    }
    51→
    52→    // /news?article=xxx  (legacy query param style)
    53→    const urlObj = new URL(url, `http://${req.headers.host}`);
    54→    const articleId = urlObj.searchParams.get('article');
    55→    if (cleanPath.startsWith('/news') && articleId) {
    56→      const article = await storage.getNews(articleId);
    57→      if (article) {
    58→        return injectMetaTagsIntoHtml(template, {
    59→          title: article.title,
    60→          description: article.excerpt || (article.content || '').replace(/<[^>]*>/g, '').substring(0, 160),
    61→          image: resolveImageUrl(article.image || '', baseUrl),
    62→          url: `${baseUrl}/news/${articleId}`,
    63→          type: 'article',
    64→          siteName: 'Peg Slam',
    65→        });
    66→      }
    67→    }
    68→
    69→    // /competition/:id
    70→    const compPathMatch = cleanPath.match(/^\/competition\/([^/]+)$/);
    71→    if (compPathMatch) {
    72→      const competition = await storage.getCompetition(compPathMatch[1]);
    73→      if (competition) {
    74→        return injectMetaTagsIntoHtml(template, {
