   129→export async function setupVite(app: Express, server: Server, storage?: any) {
   130→  const serverOptions = {
   131→    middlewareMode: true,
   132→    hmr: { server },
   133→    allowedHosts: true as const,
   134→  };
   135→
   136→  const vite = await createViteServer({
   137→    ...viteConfig,
   138→    configFile: false,
   139→    customLogger: {
   140→      ...viteLogger,
   141→      error: (msg, options) => {
   142→        viteLogger.error(msg, options);
   143→        process.exit(1);
   144→      },
   145→    },
   146→    server: serverOptions,
   147→    appType: "custom",
   148→  });
   149→
   150→  app.use(vite.middlewares);
   151→  app.use("*", async (req, res, next) => {
   152→    const url = req.originalUrl;
   153→
   154→    try {
   155→      const clientTemplate = path.resolve(
   156→        import.meta.dirname,
   157→        "..",
   158→        "client",
   159→        "index.html",
   160→      );
   161→
   162→      let template = await fs.promises.readFile(clientTemplate, "utf-8");
   163→      template = template.replace(
   164→        `src="/src/main.tsx"`,
   165→        `src="/src/main.tsx?v=${nanoid()}"`,
   166→      );
   167→      
   168→      // Inject environment variables into window.RUNTIME_CONFIG for client-side access
   169→      const runtimeConfig = {
   170→        VITE_STRIPE_PUBLIC_KEY: process.env.VITE_STRIPE_PUBLIC_KEY || '',
   171→      };
   172→      const configScript = `<script>window.RUNTIME_CONFIG = ${JSON.stringify(runtimeConfig)};</script>`;
   173→      template = template.replace('</head>', `${configScript}</head>`);
   174→      
   175→      template = await injectOgTagsForRoute(req, url, template, storage);
   176→      
   177→      const page = await vite.transformIndexHtml(url, template);
   178→      res.status(200).set({ "Content-Type": "text/html" }).end(page);
   179→    } catch (e) {
   180→      vite.ssrFixStacktrace(e as Error);
   181→      next(e);
   182→    }
   183→  });
   184→}
   185→
   186→export function serveStatic(app: Express, storage?: any) {
   187→  const distPath = path.resolve(import.meta.dirname, "public");
   188→  const basePath = process.env.EXPRESS_BASE_PATH || '';
   189→
   190→  if (!fs.existsSync(distPath)) {
   191→    throw new Error(
   192→      `Could not find the build directory: ${distPath}, make sure to build the client first`,
   193→    );
   194→  }
   195→
   196→  app.use(basePath, express.static(distPath));
   197→
   198→  app.use(`${basePath}/*`, async (req, res) => {
   199→    const url = req.originalUrl;
   200→    const indexPath = path.resolve(distPath, "index.html");
   201→    
   202→    try {
   203→      let template = await fs.promises.readFile(indexPath, "utf-8");
   204→      
   205→      // Inject environment variables into window.RUNTIME_CONFIG for client-side access
   206→      const runtimeConfig = {
   207→        VITE_STRIPE_PUBLIC_KEY: process.env.VITE_STRIPE_PUBLIC_KEY || '',
   208→      };
   209→      const configScript = `<script>window.RUNTIME_CONFIG = ${JSON.stringify(runtimeConfig)};</script>`;
   210→      template = template.replace('</head>', `${configScript}</head>`);
   211→      
   212→      template = await injectOgTagsForRoute(req, url, template, storage);
   213→      
   214→      res.status(200).set({ "Content-Type": "text/html" }).end(template);
   215→    } catch (e) {
   216→      res.sendFile(indexPath);
   217→    }
   218→  });
   219→}
