     1→import { QueryClient, QueryFunction } from "@tanstack/react-query";
     2→
     3→async function throwIfResNotOk(res: Response) {
     4→  if (!res.ok) {
     5→    const text = (await res.text()) || res.statusText;
     6→    
     7→    // Try to parse JSON error response
     8→    try {
     9→      const errorData = JSON.parse(text);
    10→      throw new Error(errorData.message || text);
    11→    } catch {
    12→      // If not JSON, throw the raw text
    13→      throw new Error(text);
    14→    }
    15→  }
    16→}
    17→
    18→// 👇 Set BASE_PATH based on VITE_BASE_PATH or fallback to empty string
    19→const BASE_PATH = import.meta.env.VITE_BASE_PATH?.replace(/\/$/, '') || '';
    20→
    21→/**
    22→ * Unified API request method with correct base path prepended.
    23→ */
    24→export async function apiRequest(
    25→  method: string,
    26→  url: string,
    27→  data?: unknown
    28→): Promise<Response> {
    29→  // 👇 Always prefix with BASE_PATH
    30→  const fullUrl = url.startsWith("/") ? `${BASE_PATH}${url}` : `${BASE_PATH}/${url}`;
    31→
    32→  const res = await fetch(fullUrl, {
    33→    method,
    34→    headers: data ? { "Content-Type": "application/json" } : {},
    35→    body: data ? JSON.stringify(data) : undefined,
    36→    credentials: "include", // includes cookies (for session auth)
    37→  });
    38→
    39→  await throwIfResNotOk(res);
    40→  return res;
    41→}
    42→
    43→type UnauthorizedBehavior = "returnNull" | "throw";
    44→
    45→export const getQueryFn: <T>(options: {
    46→  on401: UnauthorizedBehavior;
    47→}) => QueryFunction<T> =
    48→  ({ on401: unauthorizedBehavior }) =>
    49→  async ({ queryKey }) => {
    50→    const url = queryKey.join("/") as string;
    51→    const fullUrl = url.startsWith("/")
    52→      ? `${BASE_PATH}${url}`
    53→      : `${BASE_PATH}/${url}`;
    54→
    55→    const res = await fetch(fullUrl, {
    56→      credentials: "include",
    57→    });
    58→
    59→    if (unauthorizedBehavior === "returnNull" && res.status === 401) {
    60→      return null;
    61→    }
    62→
    63→    await throwIfResNotOk(res);
    64→    return await res.json();
    65→  };
    66→
    67→export const queryClient = new QueryClient({
    68→  defaultOptions: {
    69→    queries: {
    70→      queryFn: getQueryFn({ on401: "throw" }),
    71→      refetchInterval: false,
    72→      refetchOnWindowFocus: true,
    73→      refetchOnMount: true,
    74→      staleTime: 0,
    75→      retry: false,
    76→    },
    77→    mutations: {
    78→      retry: false,
    79→    },
    80→  },
    81→});
