async getAllCompetitions(): Promise<Competition[]> {
  // Use aggregation to calculate pegsBooked dynamically from actual participants.
  // This ensures the counter is always accurate regardless of the stored field value.
  const result = await this.competitions.aggregate([
    {
      $lookup: {
        from: "competition_participants",
        localField: "id",
        foreignField: "competitionId",
        as: "_participants",
      },
    },
    {
      $addFields: {
        pegsBooked: { $size: "$_participants" },
      },
    },
    {
      $project: { _participants: 0 },
    },
    { $sort: { date: 1 } },
  ]).toArray();
  return result as unknown as Competition[];
}

async getCompetition(id: string): Promise<Competition | undefined> {
  // Same real-time participant count as getAllCompetitions
  const result = await this.competitions.aggregate([
    { $match: { id } },
    {
      $lookup: {
        from: "competition_participants",
        localField: "id",
        foreignField: "competitionId",
        as: "_participants",
      },
    },
    {
      $addFields: {
        pegsBooked: { $size: "$_participants" },
      },
    },
    {
      $project: { _participants: 0 },
    },
  ]).toArray();
  return result[0] as unknown as Competition | undefined;
}

arguments.new_string:
async getAllCompetitions(): Promise<Competition[]> {
  const competitions = await this.competitions.find({}).sort({ date: 1 }).toArray();
  if (competitions.length === 0) return [];

  // Get real-time participant counts in one query across all competitions
  const countDocs = await this.competitionParticipants.aggregate([
    { $group: { _id: "$competitionId", count: { $sum: 1 } } }
  ]).toArray();
  const countMap = new Map<string, number>(countDocs.map((c: any) => [c._id as string, c.count as number]));

  return competitions.map(comp => ({
    ...comp,
    pegsBooked: countMap.get(comp.id) ?? 0,
  })) as unknown as Competition[];
}

async getCompetition(id: string): Promise<Competition | undefined> {
  const competition = await this.competitions.findOne({ id });
  if (!competition) return undefined;

  // Use countDocuments on the same collection/field that getCompetitionParticipants uses
  const pegsBooked = await this.competitionParticipants.countDocuments({ competitionId: id });

  return {
    ...competition,
    pegsBooked,
  } as unknown as Competition;
}

